   1020: squash, left wave, right tucks   1180: recover toward start */
const PERIOD = 1200;
const PARAMS = ['sy','sxz','lean','yaw','shift','headZ','headX',
                'laZ','laX','lhZ','laY','laS','raZ','raX','rhZ'];
const KEYS = [
