/* periodic non-uniform Catmull-Rom (cubic Hermite) sampler:
   exact at keyframe times, C1-smooth, identical for t and t+1200 */
function poseAt(t) {
  const tm = ((t % PERIOD) + PERIOD) % PERIOD;
  let i1 = N - 1;
  for (let k = 0; k < N; k++) {
    if (tm < KEYS[k].t) { i1 = (k - 1 + N) % N; break; }
  }
  const i0 = (i1 - 1 + N) % N, i2 = (i1 + 1) % N, i3 = (i1 + 2) % N;
  const k0 = KEYS[i0], k1 = KEYS[i1], k2 = KEYS[i2], k3 = KEYS[i3];
  const dt  = (k2.t - k1.t + PERIOD) % PERIOD;
  const dtP = (k1.t - k0.t + PERIOD) % PERIOD;
  const dtN = (k3.t - k2.t + PERIOD) % PERIOD;
  const u  = (tm - k1.t) / dt;
  const u2 = u * u, u3 = u2 * u;
  const h00 = 2*u3 - 3*u2 + 1, h10 = u3 - 2*u2 + u;
  const h01 = -2*u3 + 3*u2,    h11 = u3 - u2;
  const out = {};
  for (const p of PARAMS) {
    const v1 = k1[p], v2 = k2[p];
    const m1 = (v2 - k0[p]) * dt / (dtP + dt);
    const m2 = (k3[p] - v1) * dt / (dt + dtN);
    out[p] = h00*v1 + h10*m1 + h01*v2 + h11*m2;
  }
  return out;
}

